def get_all_links(url, base_domain):
    try:
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}
        r = requests.get(url, timeout=20, headers=headers)
        if r.status_code != 200:
            return set(), set()
        soup = BeautifulSoup(r.content, "html.parser")
        links = set()
        pdf_links = set()
        for a in soup.find_all("a", href=True):
            href = a.get("href")
            full = urljoin(url, href)
            p = urlparse(full)
            if base_domain not in p.netloc:
                continue
            if p.fragment:
                full = full.split("#", 1)
            if full.endswith(".pdf") or "/pdf/" in full:
                pdf_links.add(full)
                continue
            if any(s in full for s in ["/publication/", "/profile/", "/institution/", "/topic/", "/search/", "/question/", "/project/"]):
                links.add(full)
        return links, pdf_links
    except Exception:
        return set(), set()

